    /// The icon's outline in a 20 × 20 box, parsed once.
    pub fn path(self) -> &'static VectorPath {
        static PATHS: [OnceLock<VectorPath>; 76] = [const { OnceLock::new() }; 76];
        let index = self as usize;
        PATHS[index].get_or_init(|| {
            let (data, even_odd) = self.data();
            let mut p = VectorPath::from_svg(0x1C0_0000 + index as u64, data);
            p.even_odd = even_odd;
            p
        })
    }
